// Link the PNG catalog to the uploaded Roblox texture pages.
const fs = require('node:fs');
const path = require('node:path');
const base = require('./catalog.json');
const lettering = require('./lettering-catalog.json');
const meters = require('./meters-catalog.json');
const catalog = {
  pages: [...base.pages, ...lettering.pages, ...meters.pages],
  sprites: { ...base.sprites, ...lettering.sprites, ...meters.sprites },
};
const ids = require('./roblox-texture-ids.json');
const lines = [
  '-- Generated by assets/ui/sky-arcade/link.cjs.',
  'local Assets = {}',
  'local pages = {',
  ...catalog.pages.map(file => {
    if (!/^rbxassetid:\/\/\d+$/.test(ids[file])) throw new Error('Missing Roblox asset ID: ' + file);
    return '  ' + JSON.stringify(ids[file]) + ',';
  }),
  '}',
  'local rects = {',
  ...Object.entries(catalog.sprites).sort(([a],[b]) => a.localeCompare(b)).map(([key,r]) =>
    `  ${key} = { ${catalog.pages.indexOf(r.page)+1}, Vector2.new(${r.x}, ${r.y}), Vector2.new(${r.w}, ${r.h}) },`),
  '}',
  `
function Assets.Apply(image, key)
  local rect = assert(rects[key], "Unknown Fly High UI sprite: " .. key)
  if image:GetAttribute("HUDTextureKey") ~= key then
    image.ImageRectOffset = rect[2]
    image.ImageRectSize = rect[3]
    image.Image = pages[rect[1]]
    image:SetAttribute("HUDTextureKey", key)
  end
  return image.IsLoaded
end

function Assets.Mount(parent, key, fit)
  local image = Instance.new("ImageLabel")
  image.Name = "HUDRaster"
  image.Size = UDim2.fromScale(1, 1)
  image.BackgroundTransparency = 1
  image.BorderSizePixel = 0
  image.Active = false
  image.Selectable = false
  image.ScaleType = fit and Enum.ScaleType.Fit or Enum.ScaleType.Stretch
  image.ZIndex = parent:IsA("GuiObject") and parent.ZIndex or 1
  Assets.Apply(image, key)
  image.Parent = parent
  return image
end

function Assets.Surface(image, key, size)
  local source = rects[key][3]
  if source.X == source.Y then
    image.ScaleType = Enum.ScaleType.Fit
    return
  end
  local edgeX, top, bottom, scale = 26, 24, 32, 0.40
  if source.Y <= 36 then
    edgeX, top, bottom, scale = 16, 14, 16, 0.18
  elseif source.Y == 224 then
    edgeX, top, bottom, scale = 38, 38, 44, 0.26
  end
  image.ScaleType = Enum.ScaleType.Slice
  -- SliceCenter is relative to this sprite's ImageRect, including on a shared texture.
  image.SliceCenter = Rect.new(edgeX, top, source.X - edgeX, source.Y - bottom)
  image.SliceScale = math.max(0.01, math.min(scale, size.X / (2 * edgeX + 1), size.Y / (top + bottom + 1)))
end

function Assets.Letter(label, key, height)
  local sprite = key and "letter_" .. key
  if sprite and not rects[sprite] then sprite = "meter_" .. key end
  local image = label:FindFirstChild("HUDLettering")
  if sprite and rects[sprite] then
    if not image then
      image = Assets.Mount(label, sprite, true)
      image.Name = "HUDLettering"
      image:SetAttribute("FallbackTransparency", label.TextTransparency)
    end
    image.Visible = true
    local loaded = Assets.Apply(image, sprite)
    local size = label.AbsoluteSize
    local glyph = image.ImageRectSize
    local maxHeight = height or (label.TextScaled and size.Y or label.TextSize * 1.32)
    local scale = math.min(size.X / glyph.X, size.Y / glyph.Y, maxHeight / glyph.Y)
    image.Size = UDim2.fromOffset(glyph.X * scale, glyph.Y * scale)
    local alignment = label.TextXAlignment
    local x = alignment == Enum.TextXAlignment.Left and 0 or alignment == Enum.TextXAlignment.Right and 1 or 0.5
    image.AnchorPoint = Vector2.new(x, 0.5)
    image.Position = UDim2.fromScale(x, 0.5)
    image.ZIndex = label.ZIndex + 1
    label.TextTransparency = loaded and 1 or image:GetAttribute("FallbackTransparency")
    local outline = label:FindFirstChildOfClass("UIStroke")
    if outline then outline.Enabled = not loaded end
  elseif image then
    image.Visible = false
    label.TextTransparency = image:GetAttribute("FallbackTransparency")
    local outline = label:FindFirstChildOfClass("UIStroke")
    if outline then outline.Enabled = true end
  end
  return image
end

local meterPrefix = "meter_glyph_"
local symbols = { ["."]="dot", [","]="comma", ["+"]="plus", ["-"]="minus", ["/"]="slash", ["%"]="percent" }
local runs = setmetatable({}, { __mode = "k" })

local function meterFallback(label, loaded)
  label.TextTransparency = loaded and 1 or 0
  local outline = label:FindFirstChildOfClass("UIStroke")
  if outline then outline.Enabled = not loaded end
end

function Assets.Meter(label, value, height, prefix, suffix)
  local run = runs[label]
  if not value or value == "" then
    if run and run.frame.Visible then
      run.frame.Visible = false
      meterFallback(label, false)
    end
    return 0
  end
  if not run then
    local frame = Instance.new("Frame")
    frame.Name = "HUDMeterImages"
    frame.BackgroundTransparency = 1
    frame.Parent = label
    run = {frame = frame, images = {}, glyphs = {}}
    runs[label] = run
  end
  if run.loaded and run.value == value and run.prefix == prefix and run.suffix == suffix
    and run.height == height and run.size == label.AbsoluteSize
    and run.alignment == label.TextXAlignment and run.z == label.ZIndex
    and run.images[1] and run.images[1].IsLoaded then
    run.frame.Visible = true
    meterFallback(label, true)
    return run.width
  end
  if run.value ~= value or run.prefix ~= prefix or run.suffix ~= suffix then
    local glyphs = {}
    if prefix then table.insert(glyphs, prefix) table.insert(glyphs, "space") end
    if value == "—" then
      table.insert(glyphs, meterPrefix .. "dash")
    else
      for i = 1, #value do
        local char = value:sub(i, i)
        local key = char == " " and "space" or meterPrefix .. (symbols[char] or char)
        if key ~= "space" and not rects[key] then
          run.frame.Visible = false
          meterFallback(label, false)
          return 0
        end
        table.insert(glyphs, key)
      end
    end
    if suffix then table.insert(glyphs, "space") table.insert(glyphs, suffix) end
    run.value, run.prefix, run.suffix, run.glyphs = value, prefix, suffix, glyphs
  end
  local widths, heights, total, loaded = {}, {}, 0, true
  for i, key in run.glyphs do
    if key == "space" then
      widths[i], heights[i] = height * 0.27, 0
      if run.images[i] then run.images[i].Visible = false end
    else
      local image = run.images[i]
      if not image then
        image = Assets.Mount(run.frame, key, true)
        run.images[i] = image
      end
      image.Visible = true
      loaded = Assets.Apply(image, key) and loaded
      local size = rects[key][3]
      heights[i] = key:sub(1, #meterPrefix) == meterPrefix and height or height * 0.72
      widths[i] = heights[i] * size.X / size.Y
    end
    total += widths[i]
  end
  for i, image in run.images do if i > #run.glyphs then image.Visible = false end end
  local size = label.AbsoluteSize
  local scale = math.min(1, size.X / total, size.Y / height)
  local cursor = 0
  for i, width in widths do
    local image = run.images[i]
    if image and heights[i] > 0 then
      image.Position = UDim2.fromOffset(cursor * scale, (height - heights[i]) * scale / 2)
      image.Size = UDim2.fromOffset(width * scale, heights[i] * scale)
      image.ZIndex = label.ZIndex + 1
    end
    cursor += width
  end
  local alignment = label.TextXAlignment
  local x = alignment == Enum.TextXAlignment.Left and 0 or alignment == Enum.TextXAlignment.Right and 1 or 0.5
  run.frame.Size = UDim2.fromOffset(total * scale, height * scale)
  run.frame.Position = UDim2.fromScale(x, 0.5)
  run.frame.AnchorPoint = Vector2.new(x, 0.5)
  run.frame.ZIndex = label.ZIndex + 1
  run.frame.Visible = true
  meterFallback(label, loaded)
  run.loaded, run.height, run.size, run.alignment, run.z = loaded, height, size, alignment, label.ZIndex
  run.width = total * scale
  return loaded and total * scale or 0
end

function Assets.Preload()
  task.spawn(function()
    pcall(function()
      game:GetService("ContentProvider"):PreloadAsync(pages)
    end)
  end)
end

return Assets
`,
];
fs.writeFileSync(path.join(__dirname, '../../../audit/sources/ReplicatedStorage/FlyHigh/Modules/HUDImageAssets.luau'), lines.join('\n'));
